create table public.upload_intents(
 id uuid primary key,project_id uuid not null references public.projects(id),paper_id uuid not null,
 created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),expires_at timestamptz not null default now()+interval '24 hours',
 original_filename text not null check(length(original_filename) between 1 and 255),expected_size bigint not null check(expected_size between 1 and 4194304),expected_hash text check(expected_hash ~ '^[a-f0-9]{64}$'),
 edition_label text not null check(length(edition_label) between 1 and 200),acquired_from text not null check(length(acquired_from) between 1 and 2000),access_basis text not null check(length(access_basis) between 1 and 500),
 state text not null default 'awaiting' check(state in ('awaiting','failed','cancelled','finalized')),result_asset_id uuid,result_document_id uuid,matched_known_bytes boolean,
 foreign key(project_id,paper_id) references public.papers(project_id,id),foreign key(project_id,result_asset_id) references public.document_assets(project_id,id),foreign key(project_id,result_document_id) references public.paper_documents(project_id,id),
 check((state='finalized')=(result_asset_id is not null and result_document_id is not null and matched_known_bytes is not null)));
