create trigger audit_change after insert or update on public.upload_intents for each row execute function kg_private.capture_audit();
create index upload_intents_paper on public.upload_intents(project_id,paper_id);
create function public.begin_pdf_upload(p_id uuid,p_project uuid,p_paper uuid,p_filename text,p_size bigint,p_hash text,p_edition text,p_source text,p_access text) returns uuid language plpgsql security definer set search_path='' as $$
declare old public.upload_intents;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_project::text,0));perform kg_private.require_owner(p_project,true);
 if not exists(select from public.papers where project_id=p_project and id=p_paper and archived_at is null) then raise exception 'KG_FORBIDDEN'; end if;
 select * into old from public.upload_intents where id=p_id;
 if found then
  if old.project_id is distinct from p_project or old.paper_id is distinct from p_paper or old.original_filename is distinct from p_filename or old.expected_size is distinct from p_size or old.expected_hash is distinct from p_hash or old.edition_label is distinct from p_edition or old.acquired_from is distinct from p_source or old.access_basis is distinct from p_access or old.created_by is distinct from auth.uid() then raise exception 'KG_CONFLICT'; end if;return old.id;
 end if;
 insert into public.upload_intents(id,project_id,paper_id,created_by,original_filename,expected_size,expected_hash,edition_label,acquired_from,access_basis) values(p_id,p_project,p_paper,auth.uid(),p_filename,p_size,p_hash,p_edition,p_source,p_access);return p_id;
end; $$;
create function public.mark_pdf_upload(p_id uuid,p_state text) returns void language plpgsql security definer set search_path='' as $$
declare i public.upload_intents;
begin
 select * into i from public.upload_intents where id=p_id;if not found then raise exception 'KG_FORBIDDEN'; end if;
 perform pg_advisory_xact_lock(hashtextextended(i.project_id::text,0));perform kg_private.require_owner(i.project_id,true);
 select * into i from public.upload_intents where id=p_id for update;
 if i.state=p_state and p_state in ('failed','cancelled') then return;end if;
 if p_state not in ('failed','cancelled') or p_state is null or i.state in ('finalized','cancelled') then raise exception 'KG_CONFLICT'; end if;
 update public.upload_intents set state=p_state where id=p_id;
end; $$;
revoke all on function public.begin_pdf_upload(uuid,uuid,uuid,text,bigint,text,text,text,text),public.mark_pdf_upload(uuid,text) from public,anon,authenticated,service_role;
grant execute on function public.begin_pdf_upload(uuid,uuid,uuid,text,bigint,text,text,text,text),public.mark_pdf_upload(uuid,text) to authenticated;
