create policy verifier_asset_insert on public.document_assets for insert to kg_pdf_verifier with check(created_by=kg_private.caller_uid() and kg_private.has_role(project_id,array['owner']) and upload_state='verified' and physical_page_count is not null and verifier_version='pdf-lib@1.17.1');
create policy verifier_document_insert on public.paper_documents for insert to kg_pdf_verifier with check(created_by=kg_private.caller_uid() and kg_private.has_role(project_id,array['owner']));
create function kg_private.finalize_pdf(p_id uuid,p_hash text,p_size bigint,p_pages integer) returns jsonb language plpgsql security invoker set search_path='' as $$
declare i public.upload_intents;asset uuid;doc uuid;matched boolean;
begin
 select * into i from public.upload_intents where id=p_id;if not found then raise exception 'KG_FORBIDDEN'; end if;
 perform pg_advisory_xact_lock(hashtextextended(i.project_id::text,0));perform kg_private.require_owner(i.project_id,true);
 select * into i from public.upload_intents where id=p_id for update;
 if not exists(select from public.papers where project_id=i.project_id and id=i.paper_id and archived_at is null) then raise exception 'KG_FORBIDDEN'; end if;
 if p_hash is null or p_hash!~'^[a-f0-9]{64}$' or p_size is distinct from i.expected_size or (i.expected_hash is not null and i.expected_hash<>p_hash) or p_pages is null or p_pages not between 1 and 2000 then raise exception 'KG_MISMATCH'; end if;
 if i.state='finalized' then
  if not exists(select from public.document_assets where id=i.result_asset_id and sha256=p_hash and byte_size=p_size and physical_page_count=p_pages) then raise exception 'KG_CONFLICT'; end if;
  return jsonb_build_object('assetId',i.result_asset_id,'documentId',i.result_document_id,'matchedKnownBytes',i.matched_known_bytes);
 end if;
 if i.state='cancelled' then raise exception 'KG_CANCELLED'; end if;if i.expires_at<=now() then raise exception 'KG_EXPIRED'; end if;
 select id into asset from public.document_assets where project_id=i.project_id and sha256=p_hash and upload_state='verified';matched:=asset is not null;
 if asset is null then
  asset:=i.id;
  insert into public.document_assets(id,project_id,storage_bucket,storage_path,sha256,byte_size,mime,original_filename,upload_state,verified_at,created_by,physical_page_count,verifier_version) values(asset,i.project_id,'research-originals',i.project_id::text||'/'||i.id::text||'/original.pdf',p_hash,p_size,'application/pdf',i.original_filename,'verified',now(),kg_private.caller_uid(),p_pages,'pdf-lib@1.17.1');
 elsif not exists(select from public.document_assets where id=asset and byte_size=p_size and physical_page_count=p_pages) then raise exception 'KG_MISMATCH';end if;
 select id into doc from public.paper_documents where project_id=i.project_id and paper_id=i.paper_id and document_asset_id=asset and role='main_text';
 if doc is null then insert into public.paper_documents(project_id,paper_id,document_asset_id,role,edition_label,acquired_at,acquired_from,access_basis,created_by) values(i.project_id,i.paper_id,asset,'main_text',i.edition_label,i.created_at,i.acquired_from,i.access_basis,kg_private.caller_uid()) returning id into doc;end if;
 update public.upload_intents set state='finalized',result_asset_id=asset,result_document_id=doc,matched_known_bytes=matched where id=i.id;
 return jsonb_build_object('assetId',asset,'documentId',doc,'matchedKnownBytes',matched);
end; $$;
revoke all on function kg_private.finalize_pdf(uuid,text,bigint,integer) from public,anon,authenticated,service_role;
grant execute on function kg_private.finalize_pdf(uuid,text,bigint,integer) to kg_pdf_verifier;
-- Invoker-only: the unprovisioned worker requires this narrow role, never service_role.
create function kg_private.pdf_object_allowed(object_name text,for_insert boolean) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select from public.upload_intents i join public.projects p on p.id=i.project_id join public.papers paper on paper.id=i.paper_id and paper.project_id=p.id where object_name=i.project_id::text||'/'||i.id::text||'/original.pdf' and p.owner_user_id=auth.uid() and kg_private.has_role(p.id,array['owner']) and (not for_insert or (p.archived_at is null and paper.archived_at is null and i.state='awaiting' and i.expires_at>now())))
 or (not for_insert and exists(select from public.document_assets a join public.projects p on p.id=a.project_id where a.storage_path=object_name and p.owner_user_id=auth.uid() and kg_private.has_role(p.id,array['owner']) and a.upload_state='verified'));
$$;
revoke all on function kg_private.pdf_object_allowed(text,boolean) from public,anon,authenticated,service_role;
grant execute on function kg_private.pdf_object_allowed(text,boolean) to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('research-originals','research-originals',false,4194304,array['application/pdf']);
